CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND _user_id=auth.uid() AND role=_role); $$;
CREATE OR REPLACE FUNCTION public.get_teacher_id(_user_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.teachers WHERE user_id=_user_id AND _user_id=auth.uid() LIMIT 1; $$;
CREATE OR REPLACE FUNCTION public.get_parent_id(_user_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.parents WHERE user_id=_user_id AND _user_id=auth.uid() LIMIT 1; $$;
CREATE OR REPLACE FUNCTION public.get_student_id(_user_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.students WHERE user_id=_user_id AND _user_id=auth.uid() LIMIT 1; $$;
CREATE OR REPLACE FUNCTION public.get_user_school(_user_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT school_id FROM public.profiles WHERE id=_user_id AND _user_id=auth.uid() LIMIT 1; $$;
CREATE OR REPLACE FUNCTION public.is_school_admin(_user_id uuid, _school_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND _user_id=auth.uid() AND school_id=_school_id AND role IN ('school_owner','principal','vice_principal')); $$;
CREATE OR REPLACE FUNCTION public.is_parent_of_student(_user_id uuid, _student_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.student_parents sp JOIN public.parents p ON p.id=sp.parent_id WHERE p.user_id=_user_id AND _user_id=auth.uid() AND sp.student_id=_student_id); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role), public.get_teacher_id(uuid), public.get_parent_id(uuid), public.get_student_id(uuid), public.get_user_school(uuid), public.is_school_admin(uuid,uuid), public.is_parent_of_student(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role), public.get_teacher_id(uuid), public.get_parent_id(uuid), public.get_student_id(uuid), public.get_user_school(uuid), public.is_school_admin(uuid,uuid), public.is_parent_of_student(uuid,uuid) TO authenticated;